import {ToolRegistry} from './registry.js';
import {createChatOrchestrator} from '../chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {AIProvider, MessageChunk, SendMessageParams, ToolResultMessage} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

describe('ToolRegistry inputSchema validation acceptance', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsField: response.result.includes('ssn'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('123456789'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      }),
      async input => {
        executorInputs.push(input);
        return `22C in ${String(input.location)}`;
      }
    );

    let firstRoundToolResult = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (round === 2) {
          const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
          firstRoundToolResult = lastMessage.content[0]?.content ?? '';
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: '22C in Paris'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      registry
    );
    const session: ChatSession = {
      sessionId: 's-retry',
      userId: 'u1',
      entries: [{role: 'user', content: 'Weather in Paris?', timestamp: SENT_AT}],
    };

    const reply = await orchestrator.processMessage(session);

    expect({
      reply,
      executorInputs,
      firstAttemptRejectedForLocation:
        firstRoundToolResult.includes('location') && /required/i.test(firstRoundToolResult),
    }).toEqual({
      reply: '22C in Paris',
      executorInputs: [{location: 'Paris'}],
      firstAttemptRejectedForLocation: true,
    });
  });
});
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import {AIError} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

// One expect per test needs the rejection as a value rather than a matcher.
const outcomeOf = (call: Promise<unknown>): Promise<string> =>
  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function createErrorProvider(error: Error): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

type RecordedHook =
  | 'beforeSession'
  | 'beforeUserInput'
  | 'afterUserInput'
  | 'beforeModelResponse'
  | 'afterModelResponse'
  | 'afterSession'
  | 'onError';

// Only the named hooks are installed: one that merely exists changes the observed order.
const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
  const all: Required<OrchestratorHooks> = {
    beforeSession: async () => void callOrder.push('beforeSession'),
    beforeUserInput: async (_session, msg) => {
      callOrder.push('beforeUserInput');
      return msg;
    },
    afterUserInput: async () => void callOrder.push('afterUserInput'),
    beforeModelResponse: async (_session, systemPrompt) => {
      callOrder.push('beforeModelResponse');
      return systemPrompt;
    },
    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
    afterSession: async () => void callOrder.push('afterSession'),
    onError: async () => void callOrder.push('onError'),
  };

  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
};

// Records what the orchestrator actually sent, for tests that assert on the request.
const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
  const sent = {systemPrompt: '', lastUserContent: ''};

  return {
    sent,
    provider: {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        sent.systemPrompt = params.systemPrompt;
        const last = params.messages[params.messages.length - 1];
        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
        yield {type: 'text', text: 'ok'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    },
  };
};

describe('ChatOrchestrator hooks', () => {
  describe('beforeSession', () => {
    it('called before anything else', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['beforeSession', 'beforeUserInput', 'beforeModelResponse']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder[0]).toBe('beforeSession');
    });
  });

  describe('afterSession', () => {
    it('called after everything completes', async () => {
      const callOrder: string[] = [];
      const hooks = recordingHooks(callOrder, ['afterModelResponse', 'afterSession']);

      const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
      await orchestrator.processMessage(createSession('hello'));

      expect(callOrder).toEqual(['afterModelResponse', 'afterSession']);
    });

    it('called even when an error occurs', async () => {
      let afterSessionCalled = false;
      const hooks: OrchestratorHooks = {
        onError: async () => {},
        afterSession: async () => {
          afterSessionCalled = true;
        },
      };

      const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
        hooks,
      });
      const outcome = await outcomeOf(orchestrator.processMessage(createSession('hello')));

      expect({outcome, afterSessionCalled}).toEqual({outcome: 'boom', afterSessionCalled: true});
    });
  });

  describe('beforeUserInput', () => {
    it('receives the last user message content', async () => {
      let receivedMessage = '';
      const hooks: OrchestratorHooks = {
        beforeUserInput: async (_session, userMessage) => {
          receivedMessage = userMessage;
          return userMessage;
